```python
def _laplace_integrate(ft, t_, s_):
    # If there are undefined functions f(t) then integration is unlikely to do
    # anything useful so we skip it and given an unevaluated LaplaceTransform.
    has_undefined = any(undef.has(t_) for undef in ft.atoms(AppliedUndef)
    if has_undefined:
