```suggestion
    @property
    def mass_matrix_kin(self):
        """The kinematic "mass matrix" $\mathbf{k_{k\dot{q}}}$ of the system."""
        return self._k_kqdot if self.explicit else self._k_kqdot_implicit

    @property
    def forcing_kin(self):
        """The kinematic "forcing vector" of the system."""
        if self.explicit:
            return -(self._k_ku * Matrix(self.u) + self._f_k)
        else:
            return -(self._k_ku_implicit * Matrix(self.u) + self._f_k_implicit)

    @property
    def mass_matrix(self):
        """The mass matrix of the system."""
        if not self._fr or not self._frstar:
            raise ValueError('Need to compute Fr, Fr* first.')
        return Matrix([self._k_d, self._k_dnh])

    @property
    def forcing(self):
        """The forcing vector of the system."""
        if not self._fr or not self._frstar:
            raise ValueError('Need to compute Fr, Fr* first.')
        return -Matrix([self._f_d, self._f_dnh])

    @property
    def mass_matrix_full(self):
        """The mass matrix of the system, augmented by the kinematic
        differential equations in explicit or implicit form."""
        if not self._fr or not self._frstar:
            raise ValueError('Need to compute Fr, Fr* first.')
        o, n = len(self.u), len(self.q)
        return (self.mass_matrix_kin.row_join(zeros(n, o))).col_join(
            zeros(o, n).row_join(self.mass_matrix))

    @property
    def forcing_full(self):
        """The forcing vector of the system, augmented by the kinematic
        differential equations in explicit or implicit form."""
        return Matrix([self.forcing_kin, self.forcing])
```

Yeah I had given a thought on this but then I saw few functions related to `frac` (which I guess would be the `floor` function)  . And such a block forms a core part of `floor.as_leading_term()`. 
```
    def _eval_as_leading_term(self, x, logx=None, cdir=0):
        from sympy.calculus.accumulationbounds import AccumBounds
        arg = self.args[0]
        arg0 = arg.subs(x, 0)
        r = self.subs(x, 0)
        if arg0 is S.NaN or isinstance(arg0, AccumBounds):
            arg0 = arg.limit(x, 0, dir='-' if re(cdir).is_negative else '+')
            r = floor(arg0)
        if arg0.is_finite:
            if arg0 == r:
                if cdir == 0:
                    ndirl = arg.dir(x, cdir=-1)
                    ndir = arg.dir(x, cdir=1)
                    if ndir != ndirl:
                        raise ValueError("Two sided limit of %s around 0"
                                    "does not exist" % self)
                else:
                    ndir = arg.dir(x, cdir=cdir)
                return r - 1 if ndir.is_negative else r
            else:
                return r
        return arg.as_leading_term(x, logx=logx, cdir=cdir)
```
But yeah I'll try the other way round and maybe refactor floor and ceiling functions too along with the frac function.

For the case where we know `r` is `0`, won't 1 and 0 be the leading terms on both sides ? Maybe something like this might suffice I guess.
```
    def _eval_as_leading_term(self, x, logx=None, cdir=0):
        from sympy.calculus.accumulationbounds import AccumBounds
        arg = self.args[0]
        arg0 = arg.subs(x, 0)
        r = self.subs(x, 0)

        if arg0.is_finite:
            if r.is_zero:
                ndir = arg.dir(x, cdir=cdir)
                return S.One if ndir.is_negative else S.Zero
            else:
                return r
        elif arg0 in (S.ComplexInfinity, S.Infinity, S.NegativeInfinity):
            return AccumBounds(0, 1)
```

```suggestion
    if dummify is not False and not type(args) is str:
        reps = {}
        def _dum(args):
            # return Dummy for any non-Symbol Basic; do
            # so recursively through any iterables
            if isinstance(args, Basic):
                if not isinstance(args, Symbol):
                    d = Dummy()
                    c, a = args.as_coeff_Mul()
                    reps.setdefault(a, d/c)
                    return d
            elif iterable(args):
                return type(args)([_dum(_) for _ in args])
            return args
        args = _dum(args)
        if reps:
            def _dumreps(e):
                # replace with Dummy any non-Symbol Basic; do
                # so recursively through any iterables
                if isinstance(e, Basic):
                    return e.xreplace(reps)
                if iterable(e):
                    return type(e)([_dumreps(_) for _ in e])
                return e
            expr = _dumreps(expr)
            return lambdify(args, expr, modules=modules, printer=printer,
